// ── Provider Accessor ───────────────────────────────────────────────

export function requireCapProvider<T>(name: string, getProvider: () => T | null): T {
  const p = getProvider()
  if (p === null || p === undefined) {
    throw new TRPCError({
      code: 'PRECONDITION_FAILED',
      message: `Capability "${name}" provider not available`,
      cause: new CapRouteError(name, undefined, {
        reason: 'no-provider',
        rejected: [{ kind: 'hub-in-process', why: 'no provider bound for this cap' }],
      }),
    })
  }
  return p
}

// ── Node Routing ────────────────────────────────────────────────────

type ProxyFactory<T> = ((capName: string, nodeId: string) => T | null) | undefined

function resolveProvider<T>(
  capName: string,
  nodeId: string | undefined,
  getLocal: () => T | null,
  createProxy: ProxyFactory<T>,
): T {
  // No nodeId — try local hub provider first; if the cap lives
  // in a forked hub worker (hub/pipeline, hub/stream-broker)
  // getLocal() returns null on the hub root, so fall through to
  // createProxy('hub', ...) which leverages moleculer findCallFn
  // prefix lookup to route to the matching subnode.
  if (!nodeId || nodeId === 'hub') {
    const local = getLocal()
    if (local !== null && local !== undefined) return local
    if (createProxy) {
      const proxy = createProxy(capName, 'hub')
      if (proxy) return proxy
    }
    throw new TRPCError({
      code: 'PRECONDITION_FAILED',
      message: `Capability "${capName}" provider not available`,
      cause: new CapRouteError(capName, undefined, {
        reason: 'no-provider',
        rejected: [{ kind: 'hub-in-process', why: 'no provider bound for this cap/device' }],
      }),
    })
  }

  if (!createProxy) {
    throw new TRPCError({
      code: 'BAD_REQUEST',
      message: `Node routing not available for "${capName}"`,
    })
  }
  const proxy = createProxy(capName, nodeId)
  if (!proxy) {
    throw new TRPCError({
      code: 'PRECONDITION_FAILED',
      message: `Capability "${capName}" not available on node "${nodeId}"`,
      cause: new CapRouteError(capName, undefined, {
        reason: 'no-provider',
        nodeId,
        rejected: [{ kind: 'remote-moleculer', why: `cap not available on node "${nodeId}"` }],
      }),
    })
  }
  return proxy
}

